import React from 'react';

export default function DataTable({ machine, isAuth }) {
  if (!machine) return null;

  const entries = Object.entries(machine);
  const visible = isAuth ? entries : entries.slice(0, 10);

  return (
    <section className="table-block" aria-label="Данные машины">
      <h3>Таблица с данными</h3>
      <div className="data-grid">
        <div className="data-left">
          {visible.map(([key]) => (
            <div key={key} className="cell field-name">{key}</div>
          ))}
        </div>
        <div className="data-right">
          {visible.map(([, value], idx) => (
            <div key={idx} className="cell field-value">{value != null ? String(value) : ''}</div>
          ))}
        </div>
      </div>
    </section>
  );
}
